-- 线性表进阶：两个有序单链表的稳定归并。
INSERT INTO knowledge_point (name,description,course_id,parent_id,content_key,content_source,content_version,content_review_status,sort_order,deleted)
SELECT '有序链表归并','利用哨兵与尾指针比较两个有序链表当前结点，稳定地在线性时间内拼接。',course.id,parent.id,'cs408-linked-list-merge','AISTU',1,'REVIEWED',9,0 FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-linear-lists' LEFT JOIN knowledge_point existing ON existing.content_key='cs408-linked-list-merge' WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id,content_key,content_version,review_status,title,lesson_json,check_json)
SELECT point.id,'cs408-linked-list-merge',1,'REVIEWED','有序链表归并',JSON_OBJECT('summary','归并两个有序链表时使用哨兵和尾指针，比较两个当前结点，把较小者接到尾部并推进相应链表；其中一个耗尽后直接接上另一个余链。相等时优先取左表可保持稳定性，时间 O(m+n)。','steps',JSON_ARRAY('哨兵简化结果首结点的特殊处理','tail 始终指向已归并结果的末尾','比较两表当前键并接入较小者','相等时先接左表元素以保持稳定','一侧耗尽后直接接上另一侧余链'),'prerequisite',JSON_OBJECT('contentKey','cs408-singly-linked-list','title','单链表的结点与表示','description','先掌握沿 next 访问当前结点和后继。'),'nextStep',JSON_OBJECT('contentKey','cs408-sequential-vs-linked','title','顺序表与链表的取舍','description','最后比较两种线性表表示的适用边界。')),JSON_OBJECT('id','linked-list-merge-v1','prompt','稳定归并中，两个当前结点的键相等时应优先接入哪一侧？','options',JSON_ARRAY(JSON_OBJECT('id','LEFT_ON_EQUAL','text','左侧当前结点，保持原有相对次序'),JSON_OBJECT('id','RIGHT_ON_EQUAL','text','右侧当前结点，使尾指针少移动一次')),'correctOptionId','LEFT_ON_EQUAL','correctExplanation','正确：相等时先取左表元素，能保持两个输入表中相等元素的原相对顺序。','incorrectExplanation','不正确：固定先取右表会破坏以左表优先定义的稳定次序。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='cs408-linked-list-merge' AND existing.content_version=1 WHERE point.content_key='cs408-linked-list-merge' AND existing.id IS NULL;
